from collections import Counter

def background(grid):
    """The most frequent color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def fill_gaps(grid, color=2):
    """Every background cell sandwiched horizontally between two non-background cells becomes color."""
    B = background(grid)
    out = [row[:] for row in grid]
    for row in out:
        for j in range(1, len(row)-1):
            if row[j] == B and row[j-1] != B and row[j+1] != B:
                row[j] = color
    return out
